// Every body part in Udambu. Written for adults: a plain-English summary ("say"), then a fuller anatomy and physiology explanation ("more").
// term = anatomical/medical name. where = location. stats = typical adult figures as [label, value].
// demo = which animation in demos.js shows the part working (synced to the four "how" steps). ill = keys in illnesses.js.
const SYSTEMS = [
  { key: 'think',   name: 'Nervous system',                 say: 'The brain, spinal cord and nerves collect sensory information, process it and coordinate every movement, thought and automatic body function.', color: '#7c5cd6' },
  { key: 'senses',  name: 'Sensory organs',                 say: 'Specialised receptors in the eyes, ears, nose, tongue and skin convert light, sound, chemicals and pressure into nerve signals.', color: '#d63384' },
  { key: 'bones',   name: 'Skeletal system',                say: 'The 206 bones of the adult skeleton support the body, protect vital organs, anchor muscles and store minerals.', color: '#8a7a5c' },
  { key: 'muscles', name: 'Muscular system',                say: 'Skeletal, smooth and cardiac muscle contract to produce movement, maintain posture, move blood and food, and generate body heat.', color: '#c0392b' },
  { key: 'blood',   name: 'Cardiovascular system',          say: 'The heart and blood vessels circulate blood to deliver oxygen and nutrients to every tissue and carry away waste.', color: '#d0312d' },
  { key: 'breathe', name: 'Respiratory system',             say: 'The airways and lungs bring oxygen into the blood and remove carbon dioxide.', color: '#0077b6' },
  { key: 'food',    name: 'Digestive system',               say: 'The digestive tract and its accessory organs break food down, absorb nutrients and eliminate what remains.', color: '#c77700' },
  { key: 'clean',   name: 'Urinary system',                 say: 'The kidneys filter the blood to remove waste and balance fluids, and the bladder stores the resulting urine.', color: '#0e8c8c' },
  { key: 'guard',   name: 'Immune & lymphatic system',      say: 'White blood cells, lymphoid organs and lymph vessels detect and destroy pathogens and return tissue fluid to the blood.', color: '#0b7a55' },
  { key: 'helpers', name: 'Endocrine system',               say: 'Glands release hormones into the bloodstream to regulate growth, metabolism, stress responses and reproduction.', color: '#b5367a' },
  { key: 'grow',    name: 'Cells, genetics & reproduction', say: 'Cells and the DNA they carry build and maintain the body, and the reproductive organs make new life possible.', color: '#5b6275' },
];

const PARTS = [
  // ---------- Nervous system ----------
  { key: 'brain', name: 'Brain', term: 'Encephalon · cerebrum, cerebellum, brainstem', sys: 'think', demo: 'brain',
    where: 'Inside the skull, cushioned by cerebrospinal fluid',
    stats: [['Weight', '~1.3–1.4 kg'], ['Neurons', '~86 billion'], ['Energy use', '~20% of resting energy']],
    say: 'The brain is the control centre of the nervous system. It processes sensory input, generates thoughts and memories, and directs movement and automatic functions such as breathing.',
    more: 'The cerebrum, divided into left and right hemispheres, handles conscious thought, language, sensation and voluntary movement; its folded outer layer, the cerebral cortex, greatly increases its surface area. The cerebellum coordinates balance and fine motor control, while the brainstem regulates heart rate, breathing and sleep–wake cycles. Neurons communicate through electrical impulses and chemical neurotransmitters released at synapses. The brain is protected by the skull, three membranes called the meninges and cerebrospinal fluid, and the blood–brain barrier limits which substances can reach it from the blood. It receives about 15% of the heart’s output.',
    how: ['Sensory receptors in the eyes, ears and skin send impulses to the brain through sensory nerves.', 'The cortex integrates the input and selects a response within milliseconds.', 'Motor signals travel down the spinal cord and out along motor nerves.', 'Skeletal muscles contract and the body moves, for example to catch a ball.'],
    facts: ['The brain is about 2% of body weight but uses roughly 20% of the body’s resting energy.', 'During sleep, the clearance of metabolic waste from brain tissue increases.', 'The cerebral cortex is only 2–4 mm thick; its folds let a large surface area fit inside the skull.'],
    care: ['Aim for at least 150 minutes of moderate aerobic exercise a week, which is linked to better memory and a lower risk of dementia.', 'Get 7–9 hours of sleep and keep blood pressure under control to reduce the risk of stroke.', 'Wear a helmet when cycling or riding a two-wheeler, and do not smoke.'],
    ill: ['stroke', 'migraine', 'headache-concussion'] },
  { key: 'spinal-cord', name: 'Spinal cord', term: 'Medulla spinalis · grey and white matter', sys: 'think', demo: 'nerves',
    where: 'Inside the vertebral canal, from the base of the skull to about the first lumbar vertebra',
    stats: [['Length', '~45 cm'], ['Spinal nerve pairs', '31'], ['Width', '~1 cm']],
    say: 'The spinal cord is the main pathway between the brain and the rest of the body. It also handles fast reflexes without waiting for the brain.',
    more: 'The spinal cord is a column of nervous tissue about 45 cm long in adults, protected by the vertebrae, the meninges and cerebrospinal fluid. It has a butterfly-shaped core of grey matter containing nerve cell bodies, surrounded by white matter made of myelinated tracts that carry signals up and down. Thirty-one pairs of spinal nerves leave it through gaps between the vertebrae, each serving a specific band of skin and group of muscles. Ascending tracts carry sensation to the brain, and descending tracts carry motor commands back. Below its tapered end, a bundle of nerve roots called the cauda equina continues down the canal.',
    how: ['Heat receptors in a fingertip detect a painful stimulus.', 'A sensory neuron carries the impulse to the dorsal horn of the spinal cord.', 'An interneuron relays it directly to a motor neuron, forming a reflex arc.', 'The arm muscles contract and the hand withdraws before the brain registers pain.'],
    facts: ['The spinal cord stops growing in length before the spine does, so in adults it ends around the first or second lumbar vertebra.', 'Lumbar punctures are performed below the end of the cord so that the needle avoids it.', 'The higher a spinal cord injury occurs, the more of the body it affects.'],
    care: ['Always wear a seat belt and a helmet; road accidents and falls are leading causes of spinal cord injury.', 'Never dive into shallow or unfamiliar water.', 'Seek urgent care for back pain with leg weakness, numbness in the groin or loss of bladder control.'],
    ill: ['back-pain'] },
  { key: 'nerves', name: 'Nerves', term: 'Peripheral nervous system · neurons, myelin', sys: 'think', demo: 'nerves',
    where: 'Throughout the body, branching from the brain and spinal cord',
    stats: [['Cranial nerves', '12 pairs'], ['Spinal nerves', '31 pairs'], ['Fastest signals', '~120 m/s']],
    say: 'Peripheral nerves carry sensory information to the brain and spinal cord, and carry motor commands out to muscles and glands.',
    more: 'A nerve is a bundle of nerve fibres (axons) wrapped in connective tissue, with its own blood supply. Sensory fibres carry touch, temperature, pain and position; motor fibres trigger muscle contraction; and autonomic fibres control organs such as the heart, gut and blood vessels. Many axons are insulated by a myelin sheath, which lets the impulse jump between gaps called nodes of Ranvier and travel much faster. Neurons pass signals on by releasing neurotransmitters across a synapse. The autonomic system has a sympathetic branch (fight or flight) and a parasympathetic branch (rest and digest).',
    how: ['A stimulus opens ion channels at the sensory ending or dendrites of a neuron.', 'An action potential travels along the axon, jumping between nodes in myelinated fibres.', 'At the synapse, neurotransmitters cross the gap to the next neuron.', 'The next cell fires, and the signal is relayed within milliseconds.'],
    facts: ['The sciatic nerve is the longest and widest nerve in the body, running from the lower back to the foot.', 'Myelinated fibres conduct impulses at up to about 120 m/s, while unmyelinated pain fibres manage around 1–2 m/s.', 'Pins and needles after sitting awkwardly happen when pressure briefly disrupts a nerve’s signalling and blood supply.'],
    care: ['Keep blood sugar in range; diabetes is a leading cause of peripheral nerve damage.', 'Get enough vitamin B12 from dairy, eggs, fish or meat, or supplements on a vegan diet, and limit alcohol.', 'Take breaks from repetitive wrist movements, and check your feet daily if you have diabetes.'],
    ill: ['diabetes'] },

  // ---------- Sensory organs ----------
  { key: 'eyes', name: 'Eyes', term: 'Oculus · cornea, lens, retina', sys: 'senses', demo: 'eye',
    where: 'In the bony orbits of the skull, either side of the nose',
    stats: [['Diameter', '~24 mm'], ['Photoreceptors', '~120 million rods, ~6 million cones'], ['Blinks per minute', '~15–20']],
    say: 'The eyes focus light onto the retina, which converts it into nerve signals that the brain interprets as images.',
    more: 'Light passes through the transparent cornea, which does most of the focusing, then through the pupil, whose size is adjusted by the iris. The lens fine-tunes focus by changing shape, a process called accommodation, controlled by the ciliary muscle. The retina at the back contains rods for low-light vision and cones for colour and fine detail, which are concentrated in the fovea. Signals leave through the optic nerve, partly cross at the optic chiasm and reach the visual cortex at the back of the brain. Tears from the lacrimal glands keep the surface moist and protected.',
    how: ['Light reflected from an object reaches the eye.', 'It passes through the cornea and the pupil.', 'The lens adjusts to focus a sharp image on the retina.', 'The optic nerve carries the signal to the visual cortex, which recognises the object.'],
    facts: ['The cornea provides about two-thirds of the eye’s focusing power.', 'Each eye has a blind spot where the optic nerve leaves the retina; the brain fills in the gap.', 'The lens gradually stiffens with age, which is why most people need reading glasses after about 40.'],
    care: ['Have an eye test every 1–2 years, and regular screening if you have diabetes or a family history of glaucoma.', 'Wear UV-blocking sunglasses and do not smoke; both lower the risk of cataract.', 'At screens, follow the 20-20-20 rule: every 20 minutes, look 20 feet away for 20 seconds.'],
    ill: ['cataract', 'short-sight', 'pink-eye'] },
  { key: 'ears', name: 'Ears', term: 'Auris · ossicles, cochlea, vestibular system', sys: 'senses', demo: 'ear',
    where: 'Either side of the head; the inner ear lies within the temporal bone',
    stats: [['Hearing range', '~20–20,000 Hz'], ['Hair cells per cochlea', '~15,000'], ['Stapes length', '~3 mm']],
    say: 'The ears convert sound waves into nerve signals for hearing, and the inner ear also senses head movement for balance.',
    more: 'The outer ear funnels sound down the ear canal to the eardrum (tympanic membrane), which vibrates. In the middle ear, three ossicles, the malleus, incus and stapes, amplify the vibration and pass it to the oval window of the cochlea. Inside the fluid-filled cochlea, hair cells on the basilar membrane bend and generate signals carried by the auditory nerve to the brain. The vestibular system, made of three semicircular canals plus the utricle and saccule, detects rotation and linear movement. The Eustachian tube connects the middle ear to the back of the throat and equalises pressure.',
    how: ['Sound waves travel down the ear canal.', 'They make the eardrum vibrate.', 'The malleus, incus and stapes amplify the vibration and pass it to the inner ear.', 'Hair cells in the cochlea convert it into signals that the auditory nerve sends to the brain.'],
    facts: ['The stapes is the smallest bone in the body, about 3 mm long.', 'Cochlear hair cells do not regenerate in humans, so noise-induced hearing loss is permanent.', 'Earwax is made in the outer ear canal and normally works its way out on its own.'],
    care: ['Keep headphone volume below about 60% and limit long exposure to sounds above 85 dB.', 'Use ear protection at concerts, on building sites and around loud machinery.', 'Do not put cotton buds inside the ear canal; they can push wax deeper or damage the eardrum.'],
    ill: ['hearing-loss', 'ear-infection'] },
  { key: 'nose', name: 'Nose', term: 'Nasus · nasal cavity, olfactory epithelium', sys: 'senses', demo: 'smell',
    where: 'Centre of the face; the nasal cavity extends back to the throat',
    stats: [['Odour receptor types', '~400'], ['Air filtered per day', '~10,000 litres']],
    say: 'The nose filters, warms and moistens inhaled air, and contains the olfactory receptors that provide the sense of smell.',
    more: 'The nasal cavity is divided by the septum and lined with mucous membrane over bony ridges called turbinates, which increase the surface area for warming and moistening air. Mucus traps dust and microbes, and cilia sweep it towards the throat to be swallowed. Odour molecules dissolve in mucus at the roof of the cavity and bind to receptors on olfactory neurons. These neurons pass through the cribriform plate to the olfactory bulb, which connects directly to brain areas involved in emotion and memory. Much of what we perceive as flavour actually comes from smell.',
    how: ['Odour molecules are released into the air from a flower.', 'Inhaling carries them up into the nasal cavity.', 'They bind to receptors on olfactory neurons in the roof of the nose.', 'The olfactory bulb relays the signal to the brain, which identifies the scent.'],
    facts: ['Humans have around 400 functional types of odour receptor.', 'Olfactory neurons are replaced every one to two months, one of the few kinds of neuron that regenerate throughout life.', 'Loss of smell can be an early sign of Parkinson’s disease and was a common symptom of COVID-19.'],
    care: ['Use saline rinses for congestion, and do not use decongestant sprays for more than a few days.', 'Do not smoke; smoking dulls the sense of smell.', 'See a doctor if you lose your sense of smell for more than a few weeks.'],
    ill: ['common-cold', 'allergies', 'covid-19'] },
  { key: 'tongue', name: 'Tongue', term: 'Lingua · papillae, taste buds', sys: 'senses', demo: 'taste',
    where: 'Floor of the mouth, anchored to the hyoid bone and lower jaw',
    stats: [['Taste buds', '~2,000–8,000'], ['Taste cell lifespan', '~10–14 days'], ['Muscles', '8']],
    say: 'The tongue is a muscular organ that detects taste and is essential for chewing, swallowing and speech.',
    more: 'The tongue is made of interwoven intrinsic muscles that change its shape and extrinsic muscles that change its position. Its upper surface is covered in papillae, many of which contain taste buds. Taste receptor cells detect five basic tastes: sweet, salty, sour, bitter and umami. Signals travel through the facial, glossopharyngeal and vagus nerves to the brainstem and then to the gustatory cortex. The idea of a tongue map with separate zones for each taste is a myth; every taste can be detected across the tongue.',
    how: ['A piece of mango enters the mouth and dissolves in saliva.', 'Dissolved sugar molecules reach receptor cells in the taste buds.', 'The receptors trigger signals in the facial and glossopharyngeal nerves.', 'The gustatory cortex interprets the signal as sweet.'],
    facts: ['The tongue map is a myth: every region can detect all five basic tastes.', 'Taste receptor cells are replaced roughly every 10–14 days.', 'Taste sensitivity tends to decline with age, partly because smell declines too.'],
    care: ['Clean the tongue when brushing to reduce bacteria and bad breath.', 'Avoid tobacco and areca nut and limit alcohol, the main risk factors for mouth cancer.', 'See a dentist or doctor about any mouth ulcer or patch that lasts more than three weeks.'],
    ill: ['cancer'] },
  { key: 'skin', name: 'Skin', term: 'Cutis · epidermis, dermis', sys: 'senses', demo: 'skin',
    where: 'Covers the entire outer surface of the body',
    stats: [['Surface area', '~1.5–2 m²'], ['Share of body weight', '~15%'], ['Epidermis renewal', '~4 weeks']],
    say: 'The skin is the body’s largest organ. It forms a barrier against microbes, water loss and UV light, helps regulate temperature and provides the sense of touch.',
    more: 'The outer epidermis is made mostly of keratinocytes that form in the basal layer and move upward, flattening and dying to create a tough protective surface. Melanocytes in the basal layer produce melanin, which absorbs UV radiation. The dermis beneath contains collagen and elastin fibres, blood vessels, nerve endings, hair follicles, and sweat and sebaceous glands. When body temperature rises, sweat glands release fluid that cools the skin as it evaporates, and dermal blood vessels widen to shed heat. The skin also makes vitamin D when exposed to sunlight.',
    how: ['The epidermis and its slightly acidic surface block microbes from entering.', 'Exercise or a hot environment raises core body temperature.', 'The hypothalamus signals eccrine sweat glands to release sweat onto the skin.', 'Sweat evaporates, carrying heat away and cooling the body.'],
    facts: ['The epidermis renews itself roughly every four weeks.', 'Skin is thickest on the soles of the feet and thinnest on the eyelids.', 'Adults have roughly 2–4 million sweat glands.'],
    care: ['Use a broad-spectrum sunscreen of SPF 30 or higher and avoid strong midday sun.', 'Check your skin for new or changing moles, and see a doctor about any that grow, bleed or change colour.', 'Moisturise dry skin and do not smoke; smoking speeds up skin ageing.'],
    ill: ['sunburn', 'eczema', 'cancer', 'chickenpox'] },
  { key: 'hair-nails', name: 'Hair & nails', term: 'Pili et ungues · follicles, keratin', sys: 'senses', demo: 'grow',
    where: 'Hair grows from almost all skin except the palms and soles; nails cover the tips of the fingers and toes',
    stats: [['Scalp hairs', '~100,000'], ['Scalp hair growth', '~1 cm per month'], ['Fingernail growth', '~3.5 mm per month']],
    say: 'Hair and nails are made of keratin produced by specialised cells in the skin. Hair helps with insulation and sensation, and nails protect the fingertips and aid fine grip.',
    more: 'Each hair grows from a follicle, a pocket in the dermis with a bulb at its base where cells divide rapidly. Follicles cycle through a growth phase (anagen), which lasts several years on the scalp, a short transition phase (catagen) and a resting phase (telogen) before the hair sheds. Each follicle has a sebaceous gland and a tiny arrector pili muscle that raises the hair to cause goosebumps. Nails grow from the matrix beneath the cuticle, and the visible nail plate rests on the nail bed. The hair shaft and nail plate are dead tissue, which is why cutting them is painless.',
    how: ['Cells in the hair bulb at the base of the follicle divide rapidly.', 'The new cells fill with keratin and push the hair shaft upward.', 'During the growth phase, scalp hair lengthens by about 1 cm a month.', 'The shaft is dead keratin with no nerves, so cutting it is painless.'],
    facts: ['It is normal to shed about 50–100 scalp hairs a day.', 'Fingernails grow about 3.5 mm a month, roughly twice as fast as toenails.', 'Hair and nails do not keep growing after death; the skin dries and retracts, making them look longer.'],
    care: ['Eat enough protein, iron and zinc; deficiencies can cause thinning hair and brittle nails.', 'Keep nails trimmed and avoid biting them or cutting the cuticles, which can let infection in.', 'See a doctor about sudden hair loss or changes in nail colour or shape, which can signal other conditions.'],
    ill: ['head-lice'] },

  // ---------- Mouth (digestion starts here) ----------
  { key: 'mouth', name: 'Mouth', term: 'Cavitas oris · salivary glands', sys: 'food', demo: 'chew',
    where: 'Lower face, from the lips back to the throat',
    stats: [['Saliva per day', '~0.5–1.5 litres'], ['Major salivary glands', '3 pairs']],
    say: 'The mouth is where digestion begins. Food is chewed, mixed with saliva and shaped into a soft mass for swallowing.',
    more: 'The oral cavity is bounded by the lips, cheeks, hard and soft palate and tongue. Three pairs of major salivary glands, the parotid, submandibular and sublingual, plus many minor glands, release saliva. Saliva contains amylase to start breaking down starch, mucus for lubrication and antibacterial compounds such as lysozyme. Chewing is driven by powerful jaw muscles including the masseter and temporalis. The tongue then pushes the food mass, or bolus, back to the pharynx, triggering the swallowing reflex.',
    how: ['Food enters the mouth and the jaw muscles begin chewing.', 'Incisors and molars cut and grind it into smaller particles.', 'Saliva moistens the food and amylase starts digesting starch.', 'The tongue shapes a bolus and pushes it into the throat to be swallowed.'],
    facts: ['Saliva flow falls sharply during sleep, which is one reason bacteria multiply in the mouth overnight.', 'Dry mouth is a common side effect of many widely used medicines.', 'For its size, the masseter is one of the strongest muscles in the body.'],
    care: ['Brush twice daily with fluoride toothpaste and clean between your teeth every day.', 'Avoid tobacco, including chewing tobacco and areca nut, and limit alcohol to lower the risk of mouth cancer.', 'Drink water regularly to keep saliva flowing.'],
    ill: ['tooth-decay', 'cancer'] },
  { key: 'teeth', name: 'Teeth', term: 'Dentes · enamel, dentine, pulp', sys: 'food', demo: 'chew',
    where: 'Set in the upper and lower jaws',
    stats: [['Adult teeth', '32'], ['Milk teeth', '20'], ['Enamel', '~96% mineral']],
    say: 'Teeth cut, tear and grind food so it can be swallowed and digested efficiently.',
    more: 'Adults have 32 permanent teeth: 8 incisors, 4 canines, 8 premolars and 12 molars, including four wisdom teeth. Each tooth has a crown covered in enamel, the hardest substance in the body, over a layer of dentine. The central pulp contains nerves and blood vessels, and the root is anchored in the jawbone by the periodontal ligament. Enamel cannot regrow once lost, but early damage can be partly remineralised by fluoride and saliva. Tooth decay begins when bacteria in plaque ferment sugars into acids that dissolve enamel.',
    how: ['Incisors slice off a piece of food.', 'Premolars and molars crush and grind it.', 'Repeated chewing breaks it into fine particles, increasing the surface area for enzymes.', 'The softened food is ready to be swallowed.'],
    facts: ['Enamel is about 96% mineral, mainly hydroxyapatite, which makes it harder than bone.', 'Milk teeth begin forming in the womb, about six weeks into pregnancy.', 'Many adults have fewer than four wisdom teeth, and some have none.'],
    care: ['Brush twice a day for two minutes with fluoride toothpaste, and floss or use interdental brushes daily.', 'Cut down on how often you have sugary food and drinks.', 'See a dentist for a check-up, usually every 6–12 months.'],
    ill: ['tooth-decay'] },

  // ---------- Skeletal system ----------
  { key: 'skeleton', name: 'Skeleton', term: 'Systema skeletale · axial and appendicular', sys: 'bones', demo: 'bones',
    where: 'Throughout the body, forming its internal framework',
    stats: [['Adult bones', '206'], ['Newborn bones', '~270–300'], ['Share of body weight', '~15%']],
    say: 'The skeleton supports the body, protects internal organs, provides attachment points for muscles and stores calcium and phosphate.',
    more: 'The axial skeleton (skull, spine, ribs and sternum) protects the brain, spinal cord and chest organs, while the appendicular skeleton (the limbs and the shoulder and pelvic girdles) enables movement. Bone is living tissue made of collagen fibres hardened with calcium phosphate crystals. Osteoblasts build new bone and osteoclasts break it down, so the skeleton is continuously remodelled, with roughly 10% replaced each year in adults. Bone marrow inside many bones produces blood cells. Peak bone mass is reached around the late 20s to early 30s, after which density gradually declines.',
    how: ['Bones meet at joints, held together by ligaments.', 'Tendons attach skeletal muscles to the bones.', 'When a muscle contracts, it pulls on the bone and moves the joint like a lever.', 'Coordinated levers at the hips, knees and ankles produce a jump.'],
    facts: ['Newborns have around 270–300 bones and cartilage elements, many of which fuse to give the adult total of 206.', 'More than half the bones in the body are in the hands and feet.', 'About 99% of the body’s calcium is stored in bones and teeth.'],
    care: ['Do weight-bearing and muscle-strengthening exercise on at least two days a week.', 'Get enough calcium (about 1,000 mg a day for most adults) and vitamin D from sunlight, food or supplements.', 'Avoid smoking and heavy drinking, both of which reduce bone density.'],
    ill: ['osteoporosis', 'broken-bone'] },
  { key: 'skull', name: 'Skull', term: 'Cranium · neurocranium, facial skeleton', sys: 'bones', demo: 'shield',
    where: 'Top of the head, enclosing the brain and forming the face',
    stats: [['Bones', '22'], ['Cranial vault bones', '8'], ['Facial bones', '14']],
    say: 'The skull encloses and protects the brain, supports the face and houses the organs of sight, hearing, smell and taste.',
    more: 'The skull has 8 cranial bones that form the protective vault around the brain and 14 facial bones that shape the face. Most are joined by immovable fibrous joints called sutures. In infants, gaps between the bones called fontanelles allow the head to pass through the birth canal and the brain to grow. The mandible is the only bone that moves freely, at the temporomandibular joint. The base of the skull has openings, the largest being the foramen magnum, through which the spinal cord and many nerves and blood vessels pass.',
    how: ['The brain is soft tissue that is easily injured.', 'The skull, meninges and cerebrospinal fluid surround it in protective layers.', 'In an impact, the rigid bone absorbs and spreads the force.', 'The brain is shielded, although strong forces can still cause concussion.'],
    facts: ['The soft spots on a baby’s skull usually close by about 18 months to 2 years.', 'The mandible is the largest and strongest bone of the face, and the only skull bone that moves freely.', 'Air-filled sinuses in the skull make it lighter and add resonance to the voice.'],
    care: ['Wear a properly fitted helmet when cycling, riding a motorbike or playing contact sports.', 'In later life, reduce the risk of falls at home with good lighting and grab rails.', 'Seek medical care after any head injury followed by vomiting, confusion or drowsiness.'],
    ill: ['headache-concussion', 'broken-bone'] },
  { key: 'spine', name: 'Spine', term: 'Columna vertebralis · vertebrae, intervertebral discs', sys: 'bones', demo: 'spine',
    where: 'Along the back, from the base of the skull to the pelvis',
    stats: [['Vertebrae', '33'], ['Intervertebral discs', '23'], ['Neck vertebrae', '7']],
    say: 'The spine supports the head and trunk, allows the back to bend and twist, and protects the spinal cord.',
    more: 'The vertebral column has 7 cervical, 12 thoracic and 5 lumbar vertebrae, plus the sacrum (5 fused vertebrae) and the coccyx (usually 4 fused). Between most vertebrae sit intervertebral discs, each with a tough outer ring, the annulus fibrosus, and a gel-like centre, the nucleus pulposus, which absorb shock. Facet joints guide movement, while ligaments and back muscles stabilise the column. Seen from the side, the spine has four natural curves that help distribute load. The spinal cord runs through the vertebral canal, and spinal nerves exit between the vertebrae.',
    how: ['Vertebrae are stacked into a column with four gentle curves.', 'Intervertebral discs between them absorb shock and allow small movements.', 'Small movements at many segments add up to a large range of bending.', 'Combined with the hips, this lets you bend forward and touch your toes.'],
    facts: ['People are about 1 cm taller in the morning, because the discs lose some fluid during the day.', 'Humans and giraffes both have seven neck vertebrae.', 'Most low back pain has no specific serious cause and improves within a few weeks.'],
    care: ['Stay active; for most back pain, gentle movement aids recovery more than bed rest.', 'Strengthen your core and back muscles, and lift with your legs while keeping loads close to your body.', 'Set up your workstation with the screen at eye level, and break up long periods of sitting.'],
    ill: ['back-pain', 'osteoporosis'] },
  { key: 'ribs', name: 'Ribs', term: 'Costae · thoracic cage, costal cartilage', sys: 'bones', demo: 'breathe',
    where: 'Around the chest, from the spine to the breastbone',
    stats: [['Ribs', '24 (12 pairs)'], ['True ribs', '7 pairs'], ['Breaths per day', '~20,000']],
    say: 'The rib cage protects the heart, lungs and upper abdominal organs, and moves with every breath.',
    more: 'All 12 pairs of ribs join the thoracic vertebrae at the back. The first 7 pairs (true ribs) attach directly to the sternum through costal cartilage; pairs 8–10 (false ribs) connect indirectly through the cartilage above; and pairs 11–12 (floating ribs) have no front attachment. The intercostal muscles between the ribs work with the diaphragm to change the volume of the chest for breathing. Costal cartilage makes the cage flexible, which helps it absorb impacts. The lower ribs also shield the liver, spleen and kidneys.',
    how: ['The ribs curve around the chest from the spine to the sternum.', 'On inhaling, the external intercostal muscles lift the ribs up and out, expanding the chest.', 'On exhaling, the muscles relax and the ribs move back down and in.', 'Throughout the cycle, the cage keeps protecting the heart and lungs.'],
    facts: ['Men and women have the same number of ribs.', 'About 1 in 100–200 people has an extra cervical rib above the first rib.', 'Most rib fractures heal on their own within about 3–6 weeks.'],
    care: ['Use protective padding in contact sports.', 'After a rib injury, keep breathing deeply and coughing when needed to prevent a chest infection.', 'Maintain bone density with exercise, calcium and vitamin D.'],
    ill: ['broken-bone', 'osteoporosis'] },
  { key: 'arm-bones', name: 'Arm bones', term: 'Humerus, radius, ulna', sys: 'bones', demo: 'flex',
    where: 'From the shoulder to the wrist',
    stats: [['Bones per arm', '3 (excluding the hand)'], ['Humerus length', '~30 cm'], ['Forearm rotation', '~160–180°']],
    say: 'The bones of the arm let you reach, lift and push, and position the hand precisely.',
    more: 'The humerus runs from the shoulder, where its rounded head sits in the shallow socket of the shoulder blade, to the elbow. The forearm has two bones: the ulna on the little-finger side, which forms the main hinge at the elbow, and the radius on the thumb side. The radius rotates around the ulna, allowing the palm to turn up (supination) and down (pronation). The elbow is a hinge joint bent mainly by the biceps and brachialis and straightened by the triceps. The ulnar nerve runs close to the surface behind the elbow, which causes the funny bone sensation when it is knocked.',
    how: ['The humerus meets the radius and ulna.', 'Together they form the elbow joint.', 'The biceps and brachialis contract and the elbow flexes like a hinge.', 'The forearm and hand rise, ready to wave.'],
    facts: ['The funny bone is actually the ulnar nerve, pressed against bone at the elbow.', 'A fracture of the radius near the wrist is one of the most common fractures, often from a fall on an outstretched hand.', 'An adult’s arm span is roughly equal to their height.'],
    care: ['Warm up before sport and build shoulder and arm strength gradually.', 'Lift heavy objects close to your body using both hands.', 'Reduce fall risk and maintain bone density to prevent wrist fractures in later life.'],
    ill: ['broken-bone', 'sprain'] },
  { key: 'hand', name: 'Hands', term: 'Manus · carpals, metacarpals, phalanges', sys: 'bones', demo: 'hand',
    where: 'At the end of each forearm, beyond the wrist',
    stats: [['Bones per hand', '27'], ['Wrist bones', '8'], ['Finger bones', '14']],
    say: 'The hands combine strength with fine control, allowing precise tasks such as writing, gripping and handling small objects.',
    more: 'Each hand has 8 carpal bones in the wrist, 5 metacarpals in the palm and 14 phalanges in the fingers and thumb. Most finger movement comes from muscles in the forearm whose long tendons run through the wrist, while small muscles within the hand provide fine control. The opposable thumb, with a saddle-shaped joint at its base, can rotate to meet each fingertip. The median, ulnar and radial nerves supply sensation and movement, and the fingertips have one of the highest densities of touch receptors in the body. The carpal tunnel at the wrist carries the median nerve and the finger flexor tendons.',
    how: ['The motor cortex sends a command to pick up a pen.', 'Forearm muscles contract and pull on long flexor tendons.', 'The finger and thumb joints flex in a coordinated sequence.', 'Thumb and finger close together in a precision pinch grip.'],
    facts: ['The fingers contain no muscles; they are moved by tendons from muscles in the forearm and palm.', 'Fingerprints form in the womb and are unique, even between identical twins.', 'Carpal tunnel syndrome is caused by compression of the median nerve at the wrist.'],
    care: ['Wash your hands with soap for at least 20 seconds, especially before eating and after using the toilet.', 'Take breaks from repetitive tasks and keep your wrists in a neutral position when typing.', 'Use gloves and the right tools to avoid cuts and crush injuries.'],
    ill: ['osteoarthritis', 'broken-bone', 'sprain'] },
  { key: 'leg-bones', name: 'Leg bones', term: 'Femur, patella, tibia, fibula', sys: 'bones', demo: 'walk',
    where: 'From the hip to the ankle',
    stats: [['Femur length', '~45–50 cm'], ['Femur share of height', '~26%'], ['Bones per leg', '4 (excluding the foot)']],
    say: 'The leg bones carry the weight of the body and act as levers for standing, walking, running and climbing.',
    more: 'The femur is the longest and strongest bone in the body; its ball-shaped head fits into the socket of the pelvis to form the hip joint. At the knee it meets the tibia, the main weight-bearing bone of the lower leg, while the thinner fibula runs alongside it and anchors muscles and the ankle. The patella, or kneecap, is a bone embedded in the quadriceps tendon that improves the leverage of the thigh muscles. The neck of the femur is a common fracture site in older people with osteoporosis. Long bones grow in length at growth plates, which close in the late teens.',
    how: ['The head of the femur sits in the hip socket.', 'At the knee, the femur rests on the tibia.', 'The hip flexors and hamstrings contract and the leg swings forward.', 'Alternating swing and stance phases produce walking and running.'],
    facts: ['The femur is about a quarter of a person’s height.', 'The kneecap is cartilage at birth and only begins to turn to bone between about 3 and 6 years of age.', 'Hip fractures in older adults are often linked to osteoporosis and falls.'],
    care: ['Do weight-bearing exercise such as brisk walking, stair climbing or jogging.', 'Strengthen the thigh and hip muscles to protect the knees.', 'If you are at risk of osteoporosis, ask about a bone density scan.'],
    ill: ['broken-bone', 'osteoporosis', 'sprain'] },
  { key: 'foot', name: 'Feet', term: 'Pes · tarsals, metatarsals, phalanges', sys: 'bones', demo: 'walk',
    where: 'At the end of each leg, below the ankle',
    stats: [['Bones per foot', '26'], ['Arches per foot', '3'], ['Sweat glands (both feet)', '~250,000']],
    say: 'The feet support the body’s weight, absorb shock and provide a flexible but stable base for balance and walking.',
    more: 'Each foot has 7 tarsal bones, including the talus and the calcaneus (heel bone), 5 metatarsals and 14 phalanges. Three arches, two running lengthways and one across, are maintained by bone shape, ligaments and the plantar fascia, and they flatten slightly under load to absorb shock. The Achilles tendon attaches the calf muscles to the heel. During walking, the foot changes from a flexible shock absorber at heel strike to a rigid lever at push-off. Small muscles within the foot and the toes fine-tune balance.',
    how: ['The heel strikes the ground first.', 'The arch flattens slightly, absorbing and storing energy.', 'The calf muscles contract and the toes push off.', 'The body is propelled forward into the next step.'],
    facts: ['The two feet together contain 52 bones, about a quarter of the body’s total.', 'The Achilles tendon is the thickest and strongest tendon in the body.', 'Plantar fasciitis, irritation of the band under the arch, is one of the most common causes of heel pain.'],
    care: ['Wear well-fitting, supportive shoes, and replace running shoes when they wear out.', 'If you have diabetes, check your feet daily for cuts or sores and have them examined regularly.', 'Keep your feet clean and dry, especially between the toes, to prevent fungal infection.'],
    ill: ['sprain', 'broken-bone', 'diabetes'] },
  { key: 'joints', name: 'Joints', term: 'Articulationes · synovial joints, cartilage, ligaments', sys: 'bones', demo: 'flex',
    where: 'Wherever two or more bones meet',
    stats: [['Joints in the body', '~250–350'], ['Knee cartilage', '~2–4 mm thick']],
    say: 'Joints connect bones and allow controlled movement while keeping the skeleton stable.',
    more: 'Joints are classed as fibrous (such as skull sutures), cartilaginous (such as intervertebral discs) or synovial. Synovial joints, the most mobile, have bone ends covered in smooth articular cartilage, enclosed in a capsule lined by a synovial membrane that secretes lubricating synovial fluid. Types include hinge joints (elbow, knee), ball-and-socket joints (shoulder, hip), pivot joints (between the top two neck vertebrae) and saddle joints (base of the thumb). Ligaments connect bone to bone and limit excessive movement, while the surrounding muscles and tendons add dynamic stability. Articular cartilage has no blood supply, so it heals poorly once damaged.',
    how: ['Two bones meet within a joint capsule.', 'Articular cartilage covers the bone ends, and synovial fluid lubricates them.', 'Ligaments hold the bones in alignment.', 'Muscles move the joint smoothly through its range, as in a squat.'],
    facts: ['The knee is the largest joint in the body.', 'The shoulder is the most mobile joint, which also makes it the most commonly dislocated major joint.', 'Knuckle cracking comes from a gas cavity forming in the synovial fluid, and studies have not linked it to arthritis.'],
    care: ['Keep to a healthy weight; losing even a few kilos reduces the load on the knees.', 'Do regular low-impact exercise such as walking, swimming or cycling, plus strength training.', 'Warm up before sport and build up intensity gradually to avoid sprains.'],
    ill: ['osteoarthritis', 'sprain'] },
  { key: 'bone-marrow', name: 'Bone marrow', term: 'Medulla ossium · haematopoietic stem cells', sys: 'guard', demo: 'factory',
    where: 'Inside bones; in adults, red marrow is mainly in the pelvis, spine, ribs, breastbone and skull',
    stats: [['Red cells made', '~2 million per second'], ['Share of body weight', '~4%'], ['Red cell lifespan', '~120 days']],
    say: 'Bone marrow is the soft tissue inside bones that produces red blood cells, white blood cells and platelets.',
    more: 'Red marrow contains haematopoietic stem cells that divide and mature into every type of blood cell, a process called haematopoiesis. Yellow marrow is mostly fat and gradually replaces red marrow in the long bones during childhood and adolescence. Production is regulated by hormones such as erythropoietin, which the kidneys release when oxygen levels fall. Marrow also contains mesenchymal stem cells that can form bone, cartilage and fat. Bone marrow or stem cell transplants are used to treat leukaemia, lymphoma and some inherited blood disorders.',
    how: ['Haematopoietic stem cells live in the red marrow of bones such as the pelvis.', 'They divide and mature into red cells, white cells and platelet-forming megakaryocytes.', 'Mature cells pass through the walls of marrow sinusoids into the bloodstream.', 'They circulate around the body to carry oxygen, fight infection and stop bleeding.'],
    facts: ['The marrow produces about 2 million red blood cells every second.', 'At birth almost all marrow is red; by adulthood about half of it is yellow.', 'Most stem cell donors now give cells from their blood, after medication moves them out of the marrow, rather than having marrow taken.'],
    care: ['Eat iron-rich foods such as lentils, leafy greens, meat and fish, and get enough vitamin B12 and folate.', 'Avoid smoking and exposure to benzene, both of which can damage the marrow.', 'Consider registering as a stem cell donor.'],
    ill: ['anaemia', 'cancer'] },

  // ---------- Muscular system ----------
  { key: 'muscles', name: 'Muscles', term: 'Musculi · skeletal, smooth, cardiac', sys: 'muscles', demo: 'flex',
    where: 'Throughout the body; skeletal muscles attach to bones through tendons',
    stats: [['Skeletal muscles', '600+'], ['Share of body weight', '~30–40%'], ['Muscle types', '3']],
    say: 'Muscles contract to move the skeleton, maintain posture, pump blood, move food through the gut and generate heat.',
    more: 'Skeletal muscle is under voluntary control and made of long, striated fibres bundled into fascicles. Each fibre contains myofibrils in which actin and myosin filaments slide past each other when stimulated, shortening the muscle; this requires calcium and ATP. Muscles can only pull, so they work in opposing pairs, such as the biceps and triceps. Smooth muscle lines hollow organs and blood vessels and contracts involuntarily, while cardiac muscle is found only in the heart. Muscle mass declines from middle age, a process called sarcopenia, unless it is maintained by resistance exercise and enough protein.',
    how: ['A motor neuron releases acetylcholine at the neuromuscular junction.', 'Actin and myosin filaments slide together and the muscle shortens.', 'The contracting muscle pulls on its tendon and moves the bone.', 'The opposing muscle then contracts to return the limb.'],
    facts: ['Skeletal muscle makes up about 30–40% of adult body weight.', 'The gluteus maximus is the largest muscle in the body; the stapedius in the middle ear is the smallest.', 'Without strength training, adults can lose around 3–8% of their muscle mass per decade after 30.'],
    care: ['Do muscle-strengthening activity on at least two days a week, as the WHO recommends.', 'Eat enough protein spread through the day, from dal, eggs, dairy, fish, meat or soya.', 'Allow recovery between hard sessions and warm up before exercise.'],
    ill: ['sprain', 'back-pain'] },
  { key: 'diaphragm', name: 'Diaphragm', term: 'Diaphragma · phrenic nerve', sys: 'breathe', demo: 'breathe',
    where: 'A dome-shaped sheet under the lungs, separating the chest from the abdomen',
    stats: [['Resting breaths', '12–20 per minute'], ['Nerve supply', 'C3–C5'], ['Movement in deep breaths', 'up to ~10 cm']],
    say: 'The diaphragm is the main muscle of breathing. When it contracts, the chest expands and air is drawn into the lungs.',
    more: 'The diaphragm is a dome-shaped sheet of skeletal muscle attached to the lower ribs, sternum and lumbar spine, with a central tendon at its top. It is supplied by the phrenic nerves, which arise from the C3–C5 spinal nerves in the neck. When it contracts, it flattens and moves down, increasing chest volume and lowering pressure so that air flows into the lungs. In quiet breathing, exhalation is mostly passive, as the diaphragm relaxes and the elastic lungs recoil. Openings in the diaphragm let the oesophagus, aorta and inferior vena cava pass through; a hiatus hernia occurs when part of the stomach slides up through the oesophageal opening.',
    how: ['The phrenic nerve fires and the diaphragm contracts and flattens.', 'Chest volume increases, pressure falls and air flows into the lungs.', 'The diaphragm relaxes and rises back into its dome.', 'The lungs recoil and air is pushed out.'],
    facts: ['Hiccups are involuntary spasms of the diaphragm followed by sudden closure of the vocal cords, which makes the hic sound.', 'Because the phrenic nerve arises from C3–C5, very high neck injuries can stop breathing.', 'The diaphragm moves about 1–2 cm in quiet breathing and up to about 10 cm in very deep breaths.'],
    care: ['Practise slow diaphragmatic breathing, which can help reduce stress.', 'Stay physically active to keep the breathing muscles conditioned.', 'If you have a hiatus hernia or reflux, avoid large meals before lying down.'],
    ill: ['gerd'] },

  // ---------- Cardiovascular system ----------
  { key: 'heart', name: 'Heart', term: 'Cor · cardiac muscle', sys: 'blood', demo: 'heart',
    where: 'Centre of the chest, between the lungs, tilted to the left',
    stats: [['Weight', '250–350 g'], ['Beats per day', '~100,000'], ['Pumps per minute', '~5 litres']],
    say: 'The heart is a muscular pump that drives blood through the lungs to collect oxygen and then around the body to deliver it.',
    more: 'The heart has four chambers: two upper atria that receive blood and two lower ventricles that pump it out. The right side sends deoxygenated blood to the lungs through the pulmonary artery, and the left side pumps oxygenated blood into the aorta for the rest of the body. Four valves (tricuspid, pulmonary, mitral and aortic) keep blood moving in one direction, and their closing produces the lub-dub sounds. Each beat starts with an electrical impulse from the sinoatrial node, the natural pacemaker, which spreads through the atria to the atrioventricular node and down into the ventricles. The heart muscle receives its own blood supply through the coronary arteries.',
    how: ['Deoxygenated blood returns to the right atrium through the venae cavae.', 'The right ventricle pumps it through the pulmonary artery to the lungs to pick up oxygen.', 'Oxygenated blood returns through the pulmonary veins to the left atrium.', 'The left ventricle contracts and pumps it through the aorta to the whole body.'],
    facts: ['A normal resting heart rate for adults is 60–100 beats per minute.', 'Over a lifetime, the heart beats around 2.5–3 billion times.', 'The wall of the left ventricle is about two to three times thicker than the right, because it pumps blood around the whole body.'],
    care: ['Do at least 150 minutes of moderate aerobic activity a week.', 'Eat plenty of vegetables, fruit, whole grains and pulses, and limit salt, saturated fat and processed food.', 'Do not smoke, and have your blood pressure, cholesterol and blood sugar checked regularly.'],
    ill: ['heart-disease', 'high-blood-pressure'] },
  { key: 'blood-vessels', name: 'Blood vessels', term: 'Vasa sanguinea · arteries, capillaries, veins', sys: 'blood', demo: 'heart',
    where: 'Throughout the body, reaching almost every tissue',
    stats: [['Total length', '~100,000 km (estimate)'], ['Capillary width', '~5–10 µm'], ['Aorta width', '~2.5 cm']],
    say: 'Blood vessels form a closed network that carries blood from the heart to the tissues and back again.',
    more: 'Arteries carry blood away from the heart under high pressure and have thick, elastic, muscular walls. They branch into arterioles, which control blood flow and pressure by narrowing or widening. Capillaries, with walls just one cell thick, allow oxygen, nutrients and waste to pass between blood and tissues. Blood then drains into venules and veins, which have thinner walls and one-way valves and are helped by surrounding muscle contractions to return blood to the heart. The inner lining, the endothelium, helps regulate vessel tone and clotting, and damage to it is a key step in atherosclerosis.',
    how: ['Arteries carry oxygenated blood away from the heart.', 'In the capillaries, oxygen and nutrients diffuse into the tissues.', 'Carbon dioxide and waste diffuse from the tissues into the blood.', 'Veins return the deoxygenated blood to the heart.'],
    facts: ['A blood pressure below 120/80 mmHg is considered healthy for most adults.', 'Veins look blue through the skin because of how skin absorbs and reflects light; the blood inside is dark red.', 'Contractions of the calf muscles act as a pump that pushes blood in the leg veins back towards the heart.'],
    care: ['Keep blood pressure in check by limiting salt to under 5 g a day, as the WHO recommends.', 'Stay active and avoid long periods of sitting, especially on long journeys.', 'Do not smoke; it damages the vessel lining and speeds up atherosclerosis.'],
    ill: ['high-blood-pressure', 'heart-disease', 'stroke'] },
  { key: 'blood', name: 'Blood', term: 'Sanguis · plasma, erythrocytes, leucocytes, platelets', sys: 'blood', demo: 'blood',
    where: 'Circulates through the heart and blood vessels',
    stats: [['Volume', '~5 litres'], ['Plasma share', '~55%'], ['Red cell lifespan', '~120 days']],
    say: 'Blood transports oxygen, nutrients, hormones and immune cells around the body and carries away carbon dioxide and waste.',
    more: 'About 55% of blood is plasma, a straw-coloured fluid of water, proteins such as albumin and clotting factors, salts, glucose and hormones. Most of the rest is red blood cells, which contain haemoglobin that binds oxygen in the lungs and releases it in the tissues. White blood cells defend against infection, and platelets, fragments of larger cells, start clot formation at sites of injury. Blood also helps regulate body temperature and pH. Blood groups (ABO and Rh) depend on antigens on the surface of red cells, which is why transfusions must be matched.',
    how: ['Red blood cells pick up oxygen in the capillaries of the lungs.', 'The heart pumps them out to tissues as far away as the fingers and toes.', 'Haemoglobin releases oxygen where levels are low.', 'At an injury, platelets and clotting factors form a plug that seals the vessel.'],
    facts: ['An adult has about 5 litres of blood, roughly 7–8% of body weight.', 'Red blood cells survive about 120 days before they are removed by the spleen and liver.', 'After a donation of about 350–450 ml, plasma volume is restored within a day or two, but red cells take several weeks to replace.'],
    care: ['Eat iron-rich foods with a source of vitamin C to improve absorption, and get tested if you feel persistently tired.', 'Prevent mosquito bites with nets and repellents, and remove standing water, to avoid malaria and dengue.', 'Healthy adults can donate blood, usually every 3–4 months.'],
    ill: ['anaemia', 'malaria', 'dengue'] },

  // ---------- Respiratory system ----------
  { key: 'windpipe', name: 'Trachea (windpipe)', term: 'Trachea · cartilage rings, bronchi', sys: 'breathe', demo: 'breathe',
    where: 'Front of the neck and upper chest, in front of the oesophagus',
    stats: [['Length', '~10–12 cm'], ['Width', '~2 cm'], ['Cartilage rings', '16–20']],
    say: 'The trachea is the main airway, carrying air between the larynx and the lungs.',
    more: 'The trachea runs from the larynx down into the chest, where it divides at the carina into the left and right main bronchi. C-shaped rings of cartilage keep it open, while the open back of each ring, bridged by smooth muscle, lets the oesophagus expand during swallowing. It is lined with cilia and mucus-producing cells that trap particles, and the cilia beat upward to move mucus towards the throat, a system known as the mucociliary escalator. The right main bronchus is shorter, wider and more vertical than the left, so inhaled objects more often lodge there. During swallowing, the larynx rises and the epiglottis folds down to cover the airway entrance.',
    how: ['Air enters through the nose or mouth and passes through the larynx.', 'It flows down the trachea, which is held open by cartilage rings.', 'At the carina, the trachea divides into the left and right main bronchi.', 'Air continues into both lungs.'],
    facts: ['Cilia lining the airway beat roughly 10–20 times a second to clear mucus.', 'Inhaled objects more often lodge in the right bronchus because it is wider and more vertical.', 'Smoking damages and slows the cilia, which is one cause of smoker’s cough.'],
    care: ['Do not smoke or vape, and avoid second-hand smoke.', 'Learn first aid for choking, including back blows and abdominal thrusts.', 'Improve ventilation when cooking with wood, coal or dung fires to reduce smoke exposure.'],
    ill: ['cough-pneumonia', 'copd'] },
  { key: 'voice-box', name: 'Larynx (voice box)', term: 'Larynx · vocal folds, epiglottis', sys: 'breathe', demo: 'voice',
    where: 'Front of the neck, at the top of the trachea',
    stats: [['Cartilages', '9'], ['Male speaking pitch', '~85–155 Hz'], ['Female speaking pitch', '~165–255 Hz']],
    say: 'The larynx produces the voice and protects the airway during swallowing.',
    more: 'The larynx is a framework of nine cartilages, including the thyroid cartilage (the Adam’s apple) and the cricoid cartilage, held together by ligaments and small muscles. Inside are two vocal folds, which open for breathing and close for speech. When air from the lungs passes between the closed folds, they vibrate; pitch depends on their length and tension, and loudness on air pressure. The throat, mouth and nose then shape this sound into speech. The epiglottis and closure of the vocal folds protect the airway during swallowing, and the cough reflex expels anything that gets in.',
    how: ['Air is exhaled from the lungs up the trachea.', 'It passes between the vocal folds, which are drawn together.', 'The folds vibrate rapidly and produce a basic tone.', 'The throat, tongue and lips shape the tone into words.'],
    facts: ['At puberty, testosterone lengthens and thickens the male vocal folds, deepening the voice by about an octave.', 'In speech, adult male vocal folds typically vibrate about 85–155 times a second, and female folds about 165–255 times.', 'Whispering does not make the vocal folds vibrate; the sound comes from turbulent airflow.'],
    care: ['Stay hydrated and avoid shouting or straining your voice for long periods.', 'Do not smoke, and limit alcohol; both are major risk factors for cancer of the larynx.', 'See a doctor about hoarseness that lasts more than three weeks.'],
    ill: ['sore-throat', 'cancer'] },
  { key: 'lungs', name: 'Lungs', term: 'Pulmones · bronchioles, alveoli', sys: 'breathe', demo: 'breathe',
    where: 'Either side of the chest, inside the rib cage',
    stats: [['Alveoli', '~300–500 million'], ['Gas-exchange area', '~70 m²'], ['Breaths per day', '~20,000']],
    say: 'The lungs bring oxygen into the bloodstream and remove carbon dioxide, a waste product of metabolism.',
    more: 'The right lung has three lobes and the left has two, leaving room for the heart. The bronchi branch more than 20 times into ever smaller bronchioles, ending in clusters of tiny air sacs called alveoli. The alveolar walls are extremely thin and wrapped in capillaries, so oxygen diffuses into the blood while carbon dioxide diffuses out. A substance called surfactant reduces surface tension and stops the alveoli from collapsing. Each lung is enclosed in a double-layered membrane, the pleura, with a thin film of fluid that lets it glide smoothly during breathing.',
    how: ['Inhaled air fills the alveoli as the chest expands.', 'Oxygen diffuses across the alveolar wall into the capillary blood.', 'Carbon dioxide diffuses from the blood into the alveoli.', 'Exhalation carries the carbon dioxide out of the body.'],
    facts: ['The gas-exchange surface of the lungs is around 70 m², roughly the size of a badminton court.', 'The left lung is slightly smaller than the right, with a hollow for the heart called the cardiac notch.', 'An adult at rest breathes about 12–20 times a minute.'],
    care: ['Do not smoke; smoking is the main cause of COPD and lung cancer.', 'Keep up to date with flu, pneumococcal and COVID-19 vaccines as advised for your age and health.', 'Stay active, and limit exposure to air pollution and indoor cooking smoke.'],
    ill: ['copd', 'asthma', 'cough-pneumonia', 'covid-19'] },

  // ---------- Digestive system ----------
  { key: 'food-pipe', name: 'Oesophagus', term: 'Oesophagus · lower oesophageal sphincter', sys: 'food', demo: 'digest',
    where: 'Behind the trachea, from the throat through the chest to the stomach',
    stats: [['Length', '~25 cm'], ['Transit time for solids', '~5–10 seconds'], ['Sphincters', '2']],
    say: 'The oesophagus is a muscular tube that carries swallowed food and liquid from the throat to the stomach.',
    more: 'The oesophagus runs behind the trachea and heart and passes through the diaphragm before joining the stomach. Its wall contains layers of muscle, skeletal in the upper part and smooth in the lower part, which contract in coordinated waves called peristalsis. An upper sphincter at the top and a lower oesophageal sphincter at the bottom open to let food through and then close again. The lower sphincter normally stops acidic stomach contents flowing back up; when it relaxes at the wrong times, acid reflux and heartburn result. The lining is a tough, multi-layered epithelium that withstands the friction of swallowing but not repeated exposure to acid.',
    how: ['A bolus of food is swallowed into the upper oesophagus.', 'Circular muscle contracts just behind the bolus.', 'A wave of peristalsis pushes it down the tube.', 'The lower oesophageal sphincter relaxes and the food enters the stomach.'],
    facts: ['Because of peristalsis, food can reach the stomach even when you are upside down.', 'Solid food takes roughly 5–10 seconds to travel down the oesophagus.', 'Long-term acid reflux can change the oesophageal lining, a condition called Barrett’s oesophagus.'],
    care: ['If you have reflux, eat smaller meals and avoid lying down for 2–3 hours after eating.', 'Keep to a healthy weight and do not smoke; both reduce reflux.', 'See a doctor about difficulty swallowing or heartburn that does not go away.'],
    ill: ['gerd', 'cancer'] },
  { key: 'stomach', name: 'Stomach', term: 'Gaster · gastric glands, pylorus', sys: 'food', demo: 'digest',
    where: 'Upper left abdomen, just below the diaphragm',
    stats: [['Capacity', '~1–1.5 litres'], ['Gastric juice per day', '~2 litres'], ['Acid pH', '~1.5–3.5']],
    say: 'The stomach stores food, mixes it with acid and enzymes and begins protein digestion before passing it on to the small intestine.',
    more: 'The stomach has four regions: the cardia, fundus, body and pylorus. Its wall has three layers of smooth muscle that churn food into a semi-liquid called chyme. Gastric glands release hydrochloric acid, which kills many microbes and activates the protein-digesting enzyme pepsin, as well as intrinsic factor, which is needed to absorb vitamin B12. A thick layer of mucus and bicarbonate protects the lining from its own acid. The pyloric sphincter releases chyme into the duodenum in small amounts, and a typical meal leaves the stomach over about 2–4 hours.',
    how: ['Food enters the stomach from the oesophagus.', 'The muscular wall contracts in waves to churn it.', 'Hydrochloric acid and pepsin break down proteins, turning the food into chyme.', 'The pyloric sphincter releases chyme gradually into the small intestine.'],
    facts: ['Stomach acid typically has a pH of about 1.5–3.5.', 'Most stomach ulcers are caused by Helicobacter pylori infection or anti-inflammatory painkillers, not by stress.', 'The cells on the surface of the stomach lining are replaced every few days.'],
    care: ['Wash your hands and choose safely prepared food and clean water to prevent infection.', 'Avoid regular use of NSAID painkillers such as ibuprofen without medical advice, as they can cause ulcers.', 'Eat smaller meals and limit alcohol and smoking to reduce reflux.'],
    ill: ['gerd', 'stomach-bug', 'food-poisoning'] },
  { key: 'liver', name: 'Liver', term: 'Hepar · hepatocytes, lobules', sys: 'food', demo: 'liver',
    where: 'Upper right abdomen, under the diaphragm and lower ribs',
    stats: [['Weight', '~1.5 kg'], ['Blood flow', '~1.5 litres per minute'], ['Bile per day', '~0.4–0.8 litres']],
    say: 'The liver processes nutrients from the gut, breaks down drugs and alcohol, stores energy and makes bile and many essential proteins.',
    more: 'The liver is the largest internal organ and has a dual blood supply: the hepatic artery brings oxygenated blood, and the portal vein brings nutrient-rich blood from the intestines. Its functional units, the lobules, contain hepatocytes that metabolise carbohydrates, fats and proteins, store glycogen, vitamins and iron, and break down toxins, drugs and old red blood cells. The liver makes albumin and clotting factors, and produces bile, which drains to the gallbladder and intestine to help digest fat. It also converts ammonia into urea for the kidneys to excrete. Liver disease often causes no symptoms until it is advanced.',
    how: ['Nutrient-rich blood from the gut arrives through the portal vein.', 'Hepatocytes remove and break down toxins, drugs and waste products.', 'Excess glucose is stored as glycogen for later use.', 'Processed blood leaves through the hepatic veins to return to the heart.'],
    facts: ['The liver can regenerate; after part of it is removed, the rest can regrow to near its original size within months.', 'It receives about a quarter of the heart’s output every minute.', 'Fatty liver disease linked to metabolism affects roughly a quarter to a third of adults worldwide.'],
    care: ['Limit alcohol and keep to a healthy weight; both are major causes of fatty liver.', 'Get vaccinated against hepatitis B, and follow safe food and water hygiene to avoid hepatitis A and E.', 'Take medicines, including paracetamol and herbal supplements, only at recommended doses.'],
    ill: ['fatty-liver', 'jaundice'] },
  { key: 'gallbladder', name: 'Gallbladder', term: 'Vesica biliaris · cystic and common bile ducts', sys: 'food', demo: 'squirt',
    where: 'Tucked under the liver, upper right abdomen',
    stats: [['Length', '~7–10 cm'], ['Capacity', '~30–50 ml']],
    say: 'The gallbladder stores and concentrates bile from the liver and releases it into the small intestine to help digest fat.',
    more: 'The gallbladder is a small pear-shaped sac connected to the bile ducts by the cystic duct. Between meals, bile from the liver collects there and becomes concentrated as water is absorbed. When fatty food reaches the duodenum, the hormone cholecystokinin (CCK) makes the gallbladder contract and the sphincter of Oddi relax, so bile flows through the common bile duct into the intestine. Bile salts emulsify fat into tiny droplets, giving lipase enzymes more surface area to work on. If bile contains too much cholesterol or bilirubin, it can crystallise into gallstones.',
    how: ['The liver produces bile continuously.', 'The gallbladder stores and concentrates it between meals.', 'A fatty meal reaches the duodenum and triggers the release of cholecystokinin.', 'The gallbladder contracts and bile emulsifies the fat into small droplets.'],
    facts: ['Bilirubin from broken-down red cells is excreted in bile and gives stool its brown colour.', 'Many people with gallstones never have symptoms.', 'Gallbladder removal is a common operation; afterwards, bile flows directly from the liver into the intestine.'],
    care: ['Keep to a healthy weight, and avoid very rapid weight loss, which raises the risk of gallstones.', 'Eat a high-fibre diet with fewer refined carbohydrates and saturated fats.', 'See a doctor about severe pain in the upper right abdomen, especially with fever or yellowing of the skin.'],
    ill: ['gallstones', 'jaundice'] },
  { key: 'pancreas', name: 'Pancreas', term: 'Pancreas · acini, islets of Langerhans', sys: 'helpers', demo: 'squirt',
    where: 'Behind the stomach, across the back of the upper abdomen',
    stats: [['Length', '~15 cm'], ['Pancreatic juice per day', '~1–1.5 litres'], ['Islets', '~1 million']],
    say: 'The pancreas releases digestive enzymes into the small intestine, and hormones such as insulin and glucagon into the blood to control blood sugar.',
    more: 'The pancreas has a head nestled in the curve of the duodenum, a body and a tail reaching towards the spleen. Most of its tissue is exocrine: acinar cells make enzymes such as amylase, lipase and proteases, which drain through the pancreatic duct into the duodenum along with bicarbonate that neutralises stomach acid. The endocrine tissue forms small clusters called the islets of Langerhans. Beta cells release insulin when blood glucose rises, helping cells absorb glucose, while alpha cells release glucagon when it falls, prompting the liver to release stored glucose. Type 1 diabetes occurs when the immune system destroys the beta cells; type 2 involves insulin resistance and reduced insulin output.',
    how: ['After a meal, glucose is absorbed and blood sugar rises.', 'Beta cells in the islets of Langerhans release insulin.', 'Insulin binds to receptors on muscle, fat and liver cells.', 'The cells take up glucose for energy or storage, and blood sugar falls.'],
    facts: ['The islets of Langerhans make up only about 1–2% of the pancreas.', 'Insulin was first used to treat a person with diabetes in 1922.', 'Pancreatic enzymes are released in inactive forms so that they do not digest the pancreas itself.'],
    care: ['Limit sugary drinks and refined carbohydrates, and keep your waist size in a healthy range.', 'Be active for at least 150 minutes a week, which improves insulin sensitivity.', 'Have your blood sugar checked regularly, especially if you are over 35 or have a family history of diabetes.'],
    ill: ['diabetes', 'cancer'] },
  { key: 'small-intestine', name: 'Small intestine', term: 'Intestinum tenue · duodenum, jejunum, ileum', sys: 'food', demo: 'digest',
    where: 'Coiled in the centre of the abdomen',
    stats: [['Length', '~6 m'], ['Absorptive surface', '~30 m²'], ['Transit time', '~2–6 hours']],
    say: 'The small intestine completes the digestion of food and absorbs most nutrients into the bloodstream.',
    more: 'The small intestine has three sections: the duodenum, where bile and pancreatic juices mix with chyme, followed by the jejunum and the ileum. Its inner surface is folded and covered with finger-like villi, which are in turn covered in microvilli, greatly increasing the area for absorption. Enzymes on the microvilli break carbohydrates into simple sugars and proteins into amino acids and small peptides. Sugars and amino acids enter capillaries and travel to the liver through the portal vein, while fats are packaged into chylomicrons and enter lymphatic vessels called lacteals. The last part of the ileum absorbs vitamin B12 and recycles bile salts.',
    how: ['Chyme enters the duodenum from the stomach.', 'Bile and pancreatic enzymes break it down into small molecules.', 'Villi and microvilli absorb sugars, amino acids and fats.', 'Nutrients pass into the blood and lymph and travel to the liver and the rest of the body.'],
    facts: ['Measured after death, it is about 6–7 m long; in a living person, muscle tone keeps it shorter.', 'Folds, villi and microvilli increase its absorptive surface to roughly 30 m².', 'Coeliac disease, an immune reaction to gluten, damages the villi and impairs absorption.'],
    care: ['Eat around 30 g of fibre a day from whole grains, pulses, vegetables and fruit.', 'Wash your hands and drink safe water to avoid gut infections and worms.', 'See a doctor about ongoing diarrhoea, unexplained weight loss or blood in your stool.'],
    ill: ['stomach-bug', 'worms', 'food-poisoning'] },
  { key: 'large-intestine', name: 'Large intestine', term: 'Intestinum crassum · colon, rectum', sys: 'food', demo: 'digest',
    where: 'Frames the small intestine around the abdomen, ending at the anus',
    stats: [['Length', '~1.5 m'], ['Gut bacteria', '~38 trillion'], ['Transit time', '~1–2 days']],
    say: 'The large intestine absorbs water and salts from undigested food, hosts the gut microbiome, and forms and stores stool.',
    more: 'The large intestine begins at the caecum, where the appendix attaches, and continues as the ascending, transverse, descending and sigmoid colon before reaching the rectum and anus. It absorbs most of the remaining water and electrolytes, turning liquid waste into solid stool. Trillions of bacteria ferment dietary fibre into short-chain fatty acids, which nourish the cells of the colon, and produce vitamin K and some B vitamins. Strong mass movements a few times a day push stool into the rectum, triggering the urge to open the bowels. Colorectal cancer usually develops slowly from polyps, which is why screening is effective.',
    how: ['Undigested residue enters the caecum from the ileum.', 'The colon absorbs water and electrolytes.', 'Gut bacteria ferment fibre into short-chain fatty acids and gases.', 'The remaining material forms stool, which is stored in the rectum until it is passed.'],
    facts: ['The gut holds roughly 38 trillion bacteria, about as many as the body has human cells.', 'The colon absorbs around 1–1.5 litres of water a day.', 'Bowel cancer screening with stool tests or colonoscopy reduces deaths from the disease.'],
    care: ['Eat plenty of fibre and drink enough fluids to keep stools soft.', 'Limit red and processed meat, which are linked to bowel cancer.', 'Take part in bowel cancer screening when offered, usually from age 45–50.'],
    ill: ['constipation', 'stomach-bug', 'cancer'] },
  { key: 'appendix', name: 'Appendix', term: 'Appendix vermiformis', sys: 'food', demo: 'digest',
    where: 'Lower right abdomen, attached to the caecum',
    stats: [['Length', '~5–10 cm'], ['Lifetime appendicitis risk', '~7–8%']],
    say: 'The appendix is a narrow pouch off the large intestine. Its role is not fully understood, but it contains immune tissue and may act as a reservoir for beneficial gut bacteria.',
    more: 'The appendix is a tube closed at one end that opens into the caecum. Its wall contains abundant lymphoid tissue, suggesting a role in gut immunity, particularly early in life. One leading hypothesis is that it shelters a biofilm of helpful bacteria that can repopulate the colon after a diarrhoeal illness. Appendicitis occurs when its opening becomes blocked, often by hardened stool or swollen lymphoid tissue, leading to infection and swelling. Typically the pain starts around the navel and moves to the lower right abdomen.',
    how: ['The appendix opens off the caecum of the large intestine.', 'Its lining shelters beneficial bacteria and immune tissue.', 'After an infection flushes the gut, these bacteria can recolonise the colon.', 'The microbiome recovers and normal digestion resumes.'],
    facts: ['Appendicitis is most common between the ages of 10 and 30.', 'Removal of the appendix is one of the most frequently performed emergency operations.', 'Some cases of uncomplicated appendicitis can be treated with antibiotics alone.'],
    care: ['Seek urgent care for abdominal pain that moves to the lower right side, especially with fever or vomiting.', 'Do not take laxatives or strong painkillers for severe unexplained abdominal pain before seeing a doctor.', 'Eat a fibre-rich diet to support healthy bowel function.'],
    ill: ['appendicitis'] },

  // ---------- Urinary system ----------
  { key: 'kidneys', name: 'Kidneys', term: 'Renes · nephrons', sys: 'clean', demo: 'kidney',
    where: 'Back of the abdomen, either side of the spine, just below the ribs',
    stats: [['Nephrons per kidney', '~1 million'], ['Blood plasma filtered per day', '~180 litres'], ['Urine per day', '~1–2 litres']],
    say: 'The kidneys filter waste and excess fluid from the blood to make urine, and they help regulate blood pressure, salts and red blood cell production.',
    more: 'Each kidney contains about a million nephrons. In each nephron, a tuft of capillaries called the glomerulus filters plasma into a cup-shaped capsule, and the tubule then reabsorbs water, glucose, salts and other useful substances while secreting extra waste. About 99% of the filtered fluid is returned to the blood. The kidneys release renin to help control blood pressure and erythropoietin to stimulate red cell production, and they activate vitamin D. Urine drains from the renal pelvis down the ureters to the bladder. High blood pressure and diabetes are the leading causes of chronic kidney disease.',
    how: ['Blood enters the kidney through the renal artery.', 'Glomeruli filter water, salts and waste out of the blood.', 'Tubules reabsorb what the body needs, and filtered blood leaves through the renal vein.', 'The remaining waste and water form urine.'],
    facts: ['The kidneys receive about 20–25% of the heart’s output.', 'A person can live a healthy life with one working kidney.', 'Roughly 1 in 10 people will have a kidney stone at some point in their life.'],
    care: ['Drink enough water so that your urine is pale yellow.', 'Control blood pressure and blood sugar, and limit salt.', 'Avoid regular use of NSAID painkillers without medical advice.'],
    ill: ['kidney-stones', 'high-blood-pressure', 'diabetes', 'uti'] },
  { key: 'bladder', name: 'Bladder', term: 'Vesica urinaria · detrusor muscle, urethra', sys: 'clean', demo: 'bladder',
    where: 'Lower abdomen, in the pelvis behind the pubic bone',
    stats: [['Capacity', '~400–600 ml'], ['First urge', '~150–300 ml'], ['Visits per day', '~4–7']],
    say: 'The bladder is a muscular sac that stores urine from the kidneys and empties it through the urethra under voluntary control.',
    more: 'Urine arrives through the two ureters, which enter the bladder at an angle that prevents backflow. The bladder wall is made of smooth detrusor muscle and lined with a stretchy epithelium that lets it expand. As it fills, stretch receptors send signals through the spinal cord to the brain, creating the urge to urinate. During urination, the detrusor contracts while the internal and external urethral sphincters relax. The urethra is much shorter in women (about 4 cm) than in men (about 20 cm), which is why women get urinary tract infections more often.',
    how: ['Urine flows from the kidneys down the ureters into the bladder.', 'The detrusor muscle relaxes and the bladder expands as it fills.', 'Stretch receptors signal to the brain that the bladder is filling.', 'The detrusor contracts, the sphincters relax and the bladder empties.'],
    facts: ['Most adults urinate 4–7 times a day.', 'The female urethra is about 4 cm long and the male about 20 cm.', 'Pelvic floor exercises can reduce leaking when coughing or lifting (stress incontinence).'],
    care: ['Drink enough fluid and empty your bladder fully; avoid regularly holding urine for long periods.', 'Do pelvic floor exercises, especially after childbirth and with age.', 'Do not smoke; smoking is the biggest risk factor for bladder cancer.'],
    ill: ['uti', 'kidney-stones'] },

  // ---------- Endocrine system ----------
  { key: 'pituitary', name: 'Pituitary gland', term: 'Hypophysis · anterior and posterior lobes', sys: 'helpers', demo: 'messenger',
    where: 'Base of the brain, in a bony hollow called the sella turcica',
    stats: [['Size', '~1 cm (pea-sized)'], ['Weight', '~0.5 g'], ['Main hormones', '8']],
    say: 'The pituitary gland releases hormones that control many other glands, as well as growth, water balance and reproduction.',
    more: 'The pituitary hangs from the hypothalamus by a thin stalk and is controlled by it. The anterior lobe makes growth hormone, prolactin, thyroid-stimulating hormone, adrenocorticotropic hormone, and the reproductive hormones FSH and LH. The posterior lobe stores and releases two hormones made in the hypothalamus: antidiuretic hormone (vasopressin), which helps the kidneys conserve water, and oxytocin, which is involved in childbirth and breastfeeding. Most of its output is regulated by negative feedback, so rising levels of target hormones reduce pituitary signalling. Because it sits just below the crossing of the optic nerves, a pituitary tumour can affect vision.',
    how: ['The pituitary releases a hormone such as growth hormone.', 'The hormone travels through the bloodstream.', 'It reaches target tissues such as bone, muscle and the liver.', 'It stimulates growth and repair, partly through IGF-1 made in the liver.'],
    facts: ['Much of the day’s growth hormone is released in pulses during deep sleep.', 'It is often called the master gland, although it is itself controlled by the hypothalamus.', 'Most pituitary tumours are non-cancerous adenomas.'],
    care: ['Get 7–9 hours of good-quality sleep to support normal hormone rhythms.', 'See a doctor about unexplained headaches with vision changes, or changes in periods, weight or energy.', 'Do not use growth hormone or other hormones without medical supervision.'],
    ill: [] },
  { key: 'thyroid', name: 'Thyroid', term: 'Glandula thyroidea · thyroxine (T4), triiodothyronine (T3)', sys: 'helpers', demo: 'messenger',
    where: 'Front of the neck, below the Adam’s apple, wrapped around the trachea',
    stats: [['Weight', '~15–25 g'], ['Lobes', '2, joined by an isthmus'], ['Iodine needed', '~150 µg a day']],
    say: 'The thyroid makes hormones that set the body’s metabolic rate, affecting energy, temperature, heart rate and weight.',
    more: 'The thyroid has two lobes joined by a narrow isthmus. Its follicular cells use iodine from the diet to make thyroxine (T4) and triiodothyronine (T3); most T4 is converted to the more active T3 in the tissues. Production is controlled by thyroid-stimulating hormone (TSH) from the pituitary, in a feedback loop with the hypothalamus. Too little hormone (hypothyroidism) causes tiredness, weight gain, feeling cold and constipation, while too much (hyperthyroidism) causes weight loss, anxiety and a fast heartbeat. C cells in the thyroid also make calcitonin, which plays a minor role in calcium balance.',
    how: ['Thyroid follicles take up iodine from the blood.', 'They combine it with the amino acid tyrosine to make T4 and T3.', 'The hormones travel in the blood to cells throughout the body.', 'They raise the metabolic rate, keeping energy use and body temperature at the right level.'],
    facts: ['Iodine deficiency is the most common preventable cause of brain damage in children worldwide, which is why salt is iodised.', 'Hypothyroidism is several times more common in women than in men.', 'A TSH blood test is usually the first test of thyroid function.'],
    care: ['Use iodised salt, but keep your total salt intake low.', 'Ask for a thyroid blood test if you have persistent tiredness, weight change, or feel unusually cold or hot.', 'If prescribed thyroid medication, take it at the same time each day, usually on an empty stomach.'],
    ill: ['hypothyroidism'] },
  { key: 'adrenal', name: 'Adrenal glands', term: 'Glandulae suprarenales · cortex, medulla', sys: 'helpers', demo: 'messenger',
    where: 'On top of each kidney',
    stats: [['Weight each', '~4–5 g'], ['Layers', '2 (cortex and medulla)']],
    say: 'The adrenal glands release hormones that regulate the stress response, blood pressure, metabolism and salt balance.',
    more: 'Each adrenal gland has two parts. The outer cortex makes steroid hormones: aldosterone, which helps the kidneys retain sodium and control blood pressure; cortisol, which raises blood sugar, dampens inflammation and follows a daily rhythm; and small amounts of androgens. The inner medulla is part of the sympathetic nervous system and releases adrenaline and noradrenaline within seconds of a stress signal. Cortisol release is controlled by ACTH from the pituitary. Long-term high cortisol, whether from medication or disease, can cause weight gain, high blood pressure and weakened bones.',
    how: ['The brain perceives a sudden threat.', 'Sympathetic nerves trigger the adrenal medulla to release adrenaline.', 'Adrenaline increases heart rate and blood pressure.', 'Airways widen and glucose is released, preparing the muscles for action.'],
    facts: ['Cortisol levels are usually highest shortly after waking and lowest around midnight.', 'An adrenaline (epinephrine) injection is the emergency treatment for anaphylaxis, a severe allergic reaction.', 'Long-term steroid medicines should not be stopped suddenly, because the adrenals may take time to resume normal cortisol production.'],
    care: ['Manage ongoing stress with regular exercise, enough sleep and relaxation techniques.', 'Never stop long-term steroid medication without medical advice.', 'Have your blood pressure checked regularly; rare adrenal tumours can cause hard-to-control high blood pressure.'],
    ill: ['high-blood-pressure', 'allergies'] },

  // ---------- Immune & lymphatic system ----------
  { key: 'white-cells', name: 'White blood cells', term: 'Leucocytes · neutrophils, lymphocytes, macrophages', sys: 'guard', demo: 'fight',
    where: 'In the blood, lymph nodes, spleen and tissues; made in the bone marrow',
    stats: [['Normal count', '4,000–11,000 per µL'], ['Main types', '5'], ['Share of blood cells', 'under 1%']],
    say: 'White blood cells detect and destroy microbes, abnormal cells and debris, and build long-term immune memory.',
    more: 'There are five main types. Neutrophils are the most numerous and the first to arrive at an infection, engulfing bacteria by phagocytosis. Monocytes become macrophages in the tissues, eating microbes and dead cells and presenting fragments to other immune cells. Lymphocytes include B cells, which make antibodies, T cells, which coordinate the response and kill infected cells, and natural killer cells. Eosinophils target parasites and are involved in allergies, while basophils release histamine. After an infection or vaccination, memory B and T cells remain, allowing a faster and stronger response if the same pathogen returns.',
    how: ['A pathogen enters the body through a break in the skin.', 'Chemical signals draw neutrophils and macrophages to the site.', 'They engulf and digest the pathogen by phagocytosis.', 'Lymphocytes form memory cells that will respond faster next time.'],
    facts: ['Neutrophils make up about 40–70% of white blood cells in adults.', 'Pus consists largely of dead neutrophils, bacteria and tissue debris.', 'Vaccines train memory lymphocytes without causing the disease itself.'],
    care: ['Keep up to date with recommended vaccines, including yearly flu vaccination where advised.', 'Get 7–9 hours of sleep; regular short sleep is linked to weaker immune responses.', 'Do not smoke, and eat a varied diet with fruit, vegetables and enough protein.'],
    ill: ['flu', 'covid-19', 'fever', 'cancer'] },
  { key: 'spleen', name: 'Spleen', term: 'Lien · red pulp, white pulp', sys: 'guard', demo: 'filter',
    where: 'Upper left abdomen, behind the stomach and under the lower ribs',
    stats: [['Length', '~11 cm'], ['Weight', '~150 g']],
    say: 'The spleen filters the blood, removes old red blood cells and helps the immune system respond to infections in the bloodstream.',
    more: 'The spleen has two main types of tissue. The red pulp filters blood, removing aged or damaged red cells and recycling their iron. The white pulp contains lymphocytes that respond to bacteria and other pathogens in the blood, and it is especially important against encapsulated bacteria such as pneumococcus. The spleen also stores platelets and monocytes. In conditions such as malaria and glandular fever it can enlarge and become more vulnerable to rupture. People can live without a spleen, but they need extra vaccines and sometimes antibiotics to lower their infection risk.',
    how: ['Blood enters the spleen through the splenic artery.', 'The red pulp removes old and damaged red blood cells.', 'Immune cells in the white pulp trap and respond to pathogens.', 'Filtered blood leaves through the splenic vein.'],
    facts: ['A normal adult spleen is about the size of a clenched fist.', 'About a third of the body’s platelets are held in the spleen at any time.', 'At least 1 in 10 people has one or more small extra spleens, called accessory spleens.'],
    care: ['Avoid contact sports for several weeks after glandular fever, as an enlarged spleen can rupture.', 'If you do not have a working spleen, keep up to date with pneumococcal, meningococcal and flu vaccines.', 'Prevent malaria with nets, repellents and preventive medicine when travelling to high-risk areas.'],
    ill: ['malaria'] },
  { key: 'tonsils', name: 'Tonsils', term: 'Tonsillae palatinae · Waldeyer’s ring', sys: 'guard', demo: 'fight',
    where: 'Either side of the back of the throat',
    stats: [['Tonsil groups', '4'], ['Largest', 'In childhood']],
    say: 'The tonsils are lymphoid tissue at the entrance to the throat. They sample inhaled and swallowed microbes and help start immune responses.',
    more: 'The palatine tonsils are the ones visible at the back of the mouth, but they belong to a ring of lymphoid tissue called Waldeyer’s ring, which also includes the adenoids, the lingual tonsil at the base of the tongue and the tubal tonsils near the Eustachian tubes. Their surfaces have deep pits called crypts that trap material and pass it to the B and T cells inside. This helps the body recognise pathogens entering through the mouth and nose. Tonsils are largest in childhood and shrink after puberty. Repeated or severe tonsillitis may be treated by removing them, after which other immune tissue takes over their role.',
    how: ['Microbes enter through the mouth and nose.', 'The tonsil crypts trap and sample them.', 'Lymphocytes in the tonsils mount an immune response.', 'The infection is contained and immune memory forms.'],
    facts: ['Most cases of tonsillitis are caused by viruses and do not need antibiotics.', 'Group A streptococcus is the most common bacterial cause of tonsillitis.', 'Tonsil stones are small hardened deposits that can form in the crypts.'],
    care: ['Wash your hands often and avoid sharing cups during colds.', 'For a sore throat, use paracetamol or ibuprofen, warm drinks and rest.', 'See a doctor if a sore throat lasts more than a week or causes difficulty swallowing or breathing.'],
    ill: ['sore-throat', 'common-cold'] },
  { key: 'lymph', name: 'Lymph nodes', term: 'Nodi lymphatici · lymphatic vessels', sys: 'guard', demo: 'filter',
    where: 'Along lymphatic vessels, clustered in the neck, armpits, groin, chest and abdomen',
    stats: [['Lymph nodes', '~600'], ['Lymph returned per day', '~2–4 litres'], ['Normal size', 'usually under 1 cm']],
    say: 'Lymph nodes filter lymph fluid and act as meeting points where immune cells detect and respond to infection.',
    more: 'Fluid that leaks out of capillaries into the tissues is collected by lymphatic vessels and becomes lymph. Lymph flows through a series of lymph nodes, small bean-shaped structures packed with B cells, T cells and macrophages that trap microbes, damaged cells and cancer cells. When an infection is detected, lymphocytes multiply, which is why nodes swell and feel tender. Lymph eventually drains through the thoracic duct and right lymphatic duct into veins near the heart. Lymphatic vessels in the gut also absorb dietary fat, and blocked lymph drainage causes swelling called lymphoedema.',
    how: ['Lymph collected from the tissues flows through lymphatic vessels.', 'It filters through a lymph node.', 'Macrophages and lymphocytes trap and destroy pathogens.', 'Cleaned lymph returns to the bloodstream near the heart.'],
    facts: ['The body has roughly 600 lymph nodes.', 'Lymph has no central pump; it is moved along by muscle contractions, breathing and one-way valves.', 'Nodes swollen by an infection usually shrink back within a few weeks.'],
    care: ['Stay active; muscle movement helps lymph flow.', 'See a doctor about a lump that is hard, painless, growing or lasts more than 2–3 weeks.', 'Keep cuts clean to prevent infections that can spread into the lymphatic vessels.'],
    ill: ['cancer', 'sore-throat'] },

  // ---------- Cells, genetics & reproduction ----------
  { key: 'cells', name: 'Cells', term: 'Cellulae · nucleus, mitochondria, plasma membrane', sys: 'grow', demo: 'cells',
    where: 'Every tissue and organ in the body',
    stats: [['Human cells', '~30 trillion'], ['Cells replaced per day', '~330 billion'], ['Red cell diameter', '~7–8 µm']],
    say: 'Cells are the basic units of life. Every tissue is built from specialised cells that take in nutrients, produce energy and divide to grow and repair the body.',
    more: 'A human cell is enclosed by a plasma membrane that controls what enters and leaves. Inside, the nucleus holds the DNA, mitochondria generate ATP through aerobic respiration, ribosomes build proteins, and the endoplasmic reticulum and Golgi apparatus process and transport them. During development, cells specialise into types such as neurons, muscle fibres and epithelial cells. Most cells divide by mitosis, in which the DNA is copied and shared equally between two daughter cells, under tight control at several checkpoints. When this control fails, cells can divide uncontrollably and form a tumour.',
    how: ['The cell grows and prepares to divide.', 'It replicates its DNA so that each chromosome has two identical copies.', 'In mitosis, the chromosomes separate and the cell divides in two.', 'Two genetically identical daughter cells are formed.'],
    facts: ['An adult body has about 30 trillion human cells, most of them red blood cells.', 'The body replaces roughly 330 billion cells every day.', 'Mitochondria have their own small set of DNA, inherited from the mother.'],
    care: ['Do not smoke and limit alcohol, as both damage cellular DNA.', 'Protect your skin from UV radiation with shade, clothing and sunscreen.', 'Attend recommended cancer screening, such as cervical, breast and bowel screening.'],
    ill: ['cancer'] },
  { key: 'dna', name: 'DNA', term: 'Deoxyribonucleic acid · genes, chromosomes', sys: 'grow', demo: 'dna',
    where: 'In the nucleus of nearly every cell, and in the mitochondria',
    stats: [['Chromosomes', '46 (23 pairs)'], ['Protein-coding genes', '~20,000'], ['Base pairs', '~3.1 billion per genome']],
    say: 'DNA carries the genetic instructions for building and running the body, and passes inherited traits from parents to children.',
    more: 'DNA is a double helix of two strands made of nucleotides containing the bases adenine, thymine, guanine and cytosine; A pairs with T, and G with C. It is wound around proteins called histones and packed into 46 chromosomes in most cells. A gene is a stretch of DNA that is transcribed into RNA, which ribosomes then translate into a protein. Only about 1–2% of the genome codes for proteins, and much of the rest helps control when and where genes are switched on. Each person inherits one set of 23 chromosomes from each parent, and changes in DNA (mutations) can cause inherited conditions or, when they build up in cells, cancer.',
    how: ['DNA forms a double helix inside the nucleus of each cell.', 'Sequences of base pairs along it make up genes.', 'Enzymes transcribe a gene into messenger RNA.', 'Ribosomes translate the RNA into a protein, such as those that produce eye pigment.'],
    facts: ['Stretched out, the DNA in a single human cell would be about 2 metres long.', 'Any two people share about 99.9% of their DNA sequence.', 'Humans have about 20,000 protein-coding genes, far fewer than scientists once expected.'],
    care: ['Protect your skin from strong sun, as UV radiation damages the DNA in skin cells.', 'Avoid tobacco smoke, which contains many chemicals that cause DNA mutations.', 'Consider genetic counselling if close relatives have had cancer or inherited conditions at a young age.'],
    ill: ['cancer'] },
  { key: 'womb', name: 'Uterus', term: 'Uterus · endometrium, myometrium, cervix', sys: 'grow', demo: 'baby',
    where: 'Lower pelvis, between the bladder and the rectum',
    stats: [['Length (non-pregnant)', '~7–8 cm'], ['Menstrual cycle', '~21–35 days'], ['Pregnancy', '~40 weeks from last period']],
    say: 'The uterus is a muscular organ in the female pelvis. Its lining builds up and is shed in each menstrual cycle, and it supports and protects a developing pregnancy.',
    more: 'The uterus is a pear-shaped organ with a domed top (the fundus), a body and a narrower cervix that opens into the vagina; the fallopian tubes connect it to the ovaries. Its wall has a thick muscular layer, the myometrium, and an inner lining, the endometrium. In each menstrual cycle, oestrogen from the ovaries thickens the endometrium and, after ovulation, progesterone prepares it to receive a fertilised egg. If no pregnancy occurs, hormone levels fall and the lining is shed as a period. If an embryo implants, the placenta develops to exchange oxygen, nutrients and waste with the mother’s blood through the umbilical cord, and the uterus expands greatly before contracting during labour.',
    how: ['A fertilised egg develops into an embryo and implants in the endometrium.', 'The embryo grows inside the uterus, which expands to accommodate it.', 'The placenta and umbilical cord supply oxygen and nutrients from the mother’s blood.', 'At around 40 weeks, the myometrium contracts in labour and the baby is born.'],
    facts: ['During pregnancy, the uterus grows from about the size of a pear to reach the lower edge of the ribs.', 'A typical menstrual cycle lasts 21–35 days, with bleeding for about 2–7 days.', 'Oxytocin from the pituitary stimulates contractions during labour and the release of breast milk.'],
    care: ['Attend cervical screening as recommended, and get the HPV vaccine, which protects against most cervical cancers.', 'See a doctor about very heavy or painful periods, or bleeding between periods or after menopause.', 'Before and during pregnancy, take folic acid and attend antenatal check-ups.'],
    ill: ['anaemia', 'cancer'] },
];

const PART = Object.fromEntries(PARTS.map(p => [p.key, p]));
